import XCTest
@testable import TrillKit

/// protocol/config-v1-vectors.txt is generated by the Rust firmware-side
/// implementation; these tests check the Swift codec against it.
final class VectorTests: XCTestCase {
    struct Vector { let request: [UInt8]; let reply: [UInt8]? }

    static func loadVectors() throws -> [String: Vector] {
        let root = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
        let text = try String(contentsOf: root.appendingPathComponent("protocol/config-v1-vectors.txt"), encoding: .utf8)
        var out: [String: Vector] = [:]
        for line in text.split(separator: "\n") where !line.hasPrefix("#") {
            let f = line.components(separatedBy: " | ")
            guard f.count == 3 else { continue }
            let hex = { (s: String) -> [UInt8] in s.split(separator: " ").map { UInt8($0, radix: 16)! } }
            out[f[0]] = Vector(request: hex(f[1]), reply: f[2] == "-" ? nil : hex(f[2]))
        }
        return out
    }

    func testRequestsMatchRustEncoder() throws {
        let v = try Self.loadVectors()
        XCTAssertEqual(v.count, 17)
        XCTAssertEqual(TrillCodec.hello(1), v["hello"]!.request)
        XCTAssertEqual(TrillCodec.getConfig(2), v["get_config"]!.request)
        XCTAssertEqual(TrillCodec.setConfig(3, [(.channel, 2), (.pitchMode, 1)]), v["set_channel_steps"]!.request)
        XCTAssertEqual(TrillCodec.setConfig(4, [(.rotationFullDps, 2000)]), v["set_rotation_2000"]!.request)
        XCTAssertEqual(TrillCodec.action(9, .panic), v["action_panic"]!.request)
        XCTAssertEqual(TrillCodec.action(10, .restoreDefaults), v["action_restore_defaults"]!.request)
        // The app refuses to encode requests the device would reject.
        XCTAssertNil(TrillCodec.setConfig(5, [(.channel, 2), (.bendRange, 30)]))
        XCTAssertNil(TrillCodec.setConfig(7, [(.baseNote, 60), (.baseNote, 61)]))
        XCTAssertNil(TrillCodec.setConfig(7, []))
    }

    func testRepliesDecode() throws {
        let v = try Self.loadVectors()
        guard case let .hello(id, h)? = TrillCodec.decodeReply(v["hello"]!.reply!) else { return XCTFail("hello") }
        XCTAssertEqual(id, 1)
        XCTAssertEqual(h.protocolVersion, 1)
        XCTAssertEqual(h.firmwareString, "0.2.0")
        XCTAssertEqual(h.uptimeSeconds, 1234)
        XCTAssertEqual(h.bootID, 0x1555)
        XCTAssertEqual(h.paramCount, TrillParam.allCases.count)
        XCTAssertFalse(h.persistent)
        XCTAssertFalse(h.isPCMSynthBuild)

        guard case let .config(_, gen, persistent, cfg)? = TrillCodec.decodeReply(v["get_config"]!.reply!) else { return XCTFail("config") }
        XCTAssertEqual(gen, 0)
        XCTAssertFalse(persistent)
        XCTAssertEqual(cfg, DeviceConfig.firmwareDefaults, "Swift defaults match firmware defaults")

        guard case let .config(_, gen2, _, cfg2)? = TrillCodec.decodeReply(v["set_channel_steps"]!.reply!) else { return XCTFail("set") }
        XCTAssertEqual(gen2, 1)
        XCTAssertEqual(cfg2[.channel], 2)
        XCTAssertEqual(cfg2[.pitchMode], 1)
        XCTAssertEqual(cfg2.changes(from: .firmwareDefaults).map(\.0), [.channel, .pitchMode])

        guard case let .config(_, _, _, cfg3)? = TrillCodec.decodeReply(v["set_rotation_2000"]!.reply!) else { return XCTFail("rot") }
        XCTAssertEqual(cfg3[.rotationFullDps], 2000)

        let errors: [(String, TrillErrorCode, UInt8)] = [
            ("set_out_of_range", .outOfRange, TrillParam.bendRange.rawValue),
            ("set_unknown_param", .unknownParam, 0x63),
            ("set_duplicate", .duplicateParam, TrillParam.baseNote.rawValue),
            ("set_bad_length", .badLength, 2),
            ("action_unknown", .unknownAction, 9),
            ("too_long", .tooLong, 0),
            ("bad_version", .badVersion, 1),
            ("unknown_type", .unknownType, 0x20),
        ]
        for (name, code, detail) in errors {
            guard case let .error(_, c, d)? = TrillCodec.decodeReply(v[name]!.reply!) else { return XCTFail(name) }
            XCTAssertEqual(c, code.rawValue, name)
            XCTAssertEqual(d, detail, name)
        }
        guard case .actionAck(9, .panic)? = TrillCodec.decodeReply(v["action_panic"]!.reply!) else { return XCTFail("ack") }
        for name in ["ignored_reply_echo", "ignored_other_7d", "ignored_universal"] {
            XCTAssertNil(v[name]!.reply, name)
        }
        // Requests are never mistaken for replies (loop safety on the host).
        for (name, vec) in v where name != "ignored_reply_echo" { XCTAssertNil(TrillCodec.decodeReply(vec.request), name) }
    }

    func testMalformedRepliesAreRejected() throws {
        let good = try Self.loadVectors()["get_config"]!.reply!
        var bad = good; bad[bad.count - 2] = 0x80
        XCTAssertNil(TrillCodec.decodeReply(bad), "status byte inside")
        bad = good; bad.removeLast()
        XCTAssertNil(TrillCodec.decodeReply(bad), "no F7")
        bad = good; bad[4] = 2
        XCTAssertNil(TrillCodec.decodeReply(bad), "version")
        // Out-of-range value in a CONFIG reply (channel = 16).
        bad = good; bad[11] = 0x10
        XCTAssertNil(TrillCodec.decodeReply(bad))
        // Missing parameters.
        XCTAssertNil(TrillCodec.decodeReply(Array(good.prefix(13)) + [0xF7]))
        XCTAssertNil(TrillCodec.decodeReply([]))
        XCTAssertNil(TrillCodec.decodeReply([UInt8](repeating: 0, count: 100)))
    }
}
